param([switch]$CalledByRunner,[switch]$NoGui)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12
$Root=Split-Path -Parent $MyInvocation.MyCommand.Path;$Models=Join-Path $Root 'Models\v6';$LogDir=Join-Path $Root 'logs';$LogFile=Join-Path $LogDir 'prepare_models.log';New-Item -ItemType Directory -Force -Path $Models,$LogDir|Out-Null
$Specs=@(
 [pscustomobject]@{Name='Medium 检测模型';File='PP-OCRv6_det_medium.onnx';Min=40000000L;Sha='92078b7355007ccfffcd4c8cd441a3afd4538904d06881b29a155e1e679907c2';Urls=@('https://www.modelscope.cn/models/RapidAI/RapidOCR/resolve/v3.9.2/onnx/PP-OCRv6/det/PP-OCRv6_det_medium.onnx','https://www.modelscope.cn/models/RapidAI/RapidOCR/resolve/master/onnx/PP-OCRv6/det/PP-OCRv6_det_medium.onnx')},
 [pscustomobject]@{Name='Medium 识别模型';File='PP-OCRv6_rec_medium.onnx';Min=50000000L;Sha='eef444829dbbe18d7fea59a3f6eb75647518d2b3a9568d27c92e42940204894b';Urls=@('https://www.modelscope.cn/models/RapidAI/RapidOCR/resolve/v3.9.2/onnx/PP-OCRv6/rec/PP-OCRv6_rec_medium.onnx','https://www.modelscope.cn/models/RapidAI/RapidOCR/resolve/master/onnx/PP-OCRv6/rec/PP-OCRv6_rec_medium.onnx')},
 [pscustomobject]@{Name='PP-OCRv6 字典';File='ppocrv6_medium_dict.txt';Min=50000L;Sha='b5f2bfe2bdd9448429e3e82b51c789775d9b42f2403d082b00662eb77e401c5d';Urls=@('https://raw.githubusercontent.com/PaddlePaddle/PaddleOCR/main/ppocr/utils/dict/ppocrv6_dict.txt','https://gitee.com/paddlepaddle/PaddleOCR/raw/main/ppocr/utils/dict/ppocrv6_dict.txt')}
)
$GuiMode=-not $NoGui;$GuiForm=$null
if($GuiMode){Add-Type -AssemblyName System.Windows.Forms;Add-Type -AssemblyName System.Drawing;[Windows.Forms.Application]::EnableVisualStyles();$GuiForm=New-Object Windows.Forms.Form;$GuiForm.Text='OCRCaptureTool Full · 模型准备';$GuiForm.StartPosition='CenterScreen';$GuiForm.FormBorderStyle='FixedDialog';$GuiForm.MaximizeBox=$false;$GuiForm.Width=560;$GuiForm.Height=205;$GuiForm.BackColor=[Drawing.Color]::FromArgb(24,28,36);$GuiForm.ForeColor=[Drawing.Color]::FromArgb(235,239,247);$GuiTitle=New-Object Windows.Forms.Label;$GuiTitle.Left=24;$GuiTitle.Top=22;$GuiTitle.Width=490;$GuiTitle.Height=28;$GuiTitle.Font=New-Object Drawing.Font('Microsoft YaHei UI',11,[Drawing.FontStyle]::Bold);$GuiTitle.Text='正在校验 PP-OCRv6 Medium';$GuiForm.Controls.Add($GuiTitle);$GuiDetail=New-Object Windows.Forms.Label;$GuiDetail.Left=24;$GuiDetail.Top=58;$GuiDetail.Width=490;$GuiDetail.Height=35;$GuiDetail.Font=New-Object Drawing.Font('Microsoft YaHei UI',9);$GuiDetail.ForeColor=[Drawing.Color]::FromArgb(158,170,190);$GuiDetail.Text='已有完整模型时不会联网。';$GuiForm.Controls.Add($GuiDetail);$GuiProgress=New-Object Windows.Forms.ProgressBar;$GuiProgress.Left=24;$GuiProgress.Top=105;$GuiProgress.Width=450;$GuiProgress.Height=10;$GuiProgress.Minimum=0;$GuiProgress.Maximum=100;$GuiForm.Controls.Add($GuiProgress);$GuiPercent=New-Object Windows.Forms.Label;$GuiPercent.Left=480;$GuiPercent.Top=98;$GuiPercent.Width=48;$GuiPercent.Height=25;$GuiPercent.TextAlign='MiddleRight';$GuiPercent.Font=New-Object Drawing.Font('Segoe UI',9,[Drawing.FontStyle]::Bold);$GuiPercent.Text='0%';$GuiForm.Controls.Add($GuiPercent);$hint=New-Object Windows.Forms.Label;$hint.Left=24;$hint.Top=132;$hint.Width=500;$hint.Height=25;$hint.Font=New-Object Drawing.Font('Microsoft YaHei UI',8);$hint.ForeColor=[Drawing.Color]::FromArgb(112,124,145);$hint.Text='优先复用本机相同模型；只有模型缺失或损坏时才下载。';$GuiForm.Controls.Add($hint);$GuiForm.Show();[Windows.Forms.Application]::DoEvents()}
function Set-Gui([int]$p,[string]$t,[string]$d){if(-not $GuiMode -or $null -eq $GuiForm){return};$v=[Math]::Max(0,[Math]::Min(100,$p));$GuiProgress.Value=$v;$GuiPercent.Text="$v%";if($t){$GuiTitle.Text=$t};if($d){$GuiDetail.Text=$d};[Windows.Forms.Application]::DoEvents()}
function Log([string]$m){Add-Content -LiteralPath $LogFile -Value("[{0}] {1}" -f(Get-Date -Format 'yyyy-MM-dd HH:mm:ss'),$m)-Encoding UTF8}
function Hash-Ok($p,$sha){if(-not(Test-Path -LiteralPath $p)){return $false};return (Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant() -eq $sha.ToLowerInvariant()}
function Size-Text([long]$n){if($n-ge 1MB){return('{0:N1} MB'-f($n/1MB))};return('{0:N1} KB'-f($n/1KB))}
function Find-Reusable($spec){$roots=New-Object Collections.Generic.List[string];$parent=Split-Path -Parent $Root;Get-ChildItem -LiteralPath $parent -Directory -ErrorAction SilentlyContinue|Where-Object{$_.Name -match 'ScreenAssistant|OCRCaptureTool' -and $_.FullName -ne $Root}|ForEach-Object{$roots.Add($_.FullName)};foreach($extra in @((Join-Path $env:LOCALAPPDATA 'ScreenAssistant'),(Join-Path $env:LOCALAPPDATA 'LonzilTools\ScreenAssistant'),(Join-Path $env:LOCALAPPDATA 'OCRCaptureTool'),(Join-Path $env:LOCALAPPDATA 'OCRCaptureToolLite'))){if($extra -and(Test-Path -LiteralPath $extra)){$roots.Add($extra)}};foreach($base in $roots){try{foreach($f in Get-ChildItem -LiteralPath $base -Recurse -File -Filter $spec.File -ErrorAction SilentlyContinue){if($f.Length-ge $spec.Min -and(Hash-Ok $f.FullName $spec.Sha)){return $f.FullName}}}catch{}};return $null}
function Download-One($spec,$target,[int]$base,[int]$span){Add-Type -AssemblyName System.Net.Http -ErrorAction SilentlyContinue;$errs=@();foreach($url in $spec.Urls){$tmp="$target.download";Remove-Item $tmp -Force -ErrorAction SilentlyContinue;try{Log "download $($spec.Name) from $url";Set-Gui $base ("正在下载 "+$spec.Name) '仅缺失时联网，下载完成后会校验 SHA-256。';$handler=New-Object Net.Http.HttpClientHandler;$handler.AllowAutoRedirect=$true;$client=New-Object Net.Http.HttpClient($handler);$client.Timeout=[TimeSpan]::FromMinutes(20);$client.DefaultRequestHeaders.UserAgent.ParseAdd('OCRCaptureTool/0.2.1');try{$resp=$client.GetAsync($url,[Net.Http.HttpCompletionOption]::ResponseHeadersRead).GetAwaiter().GetResult();$resp.EnsureSuccessStatusCode();$total=$resp.Content.Headers.ContentLength;$input=$resp.Content.ReadAsStreamAsync().GetAwaiter().GetResult();$output=[IO.File]::Open($tmp,[IO.FileMode]::Create,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$buf=New-Object byte[](1048576);[long]$done=0;while(($read=$input.Read($buf,0,$buf.Length))-gt 0){$output.Write($buf,0,$read);$done+=$read;if($total -and $total-gt 0){$pct=[int](100*$done/$total);Set-Gui($base+[int]($span*$pct/100)) ("正在下载 "+$spec.Name) ((Size-Text $done)+' / '+(Size-Text $total))}}}finally{$output.Dispose();$input.Dispose()}}finally{$client.Dispose();$handler.Dispose()};if((Get-Item $tmp).Length-lt $spec.Min -or -not(Hash-Ok $tmp $spec.Sha)){throw '下载文件大小/SHA-256 校验失败。'};Move-Item $tmp $target -Force;return}catch{$errs+="$url -> $($_.Exception.Message)";Log $errs[-1];Remove-Item $tmp -Force -ErrorAction SilentlyContinue}};throw($spec.Name+" 下载失败。`n"+($errs-join"`n"))}
try{Write-Host 'OCRCaptureTool Full - PP-OCRv6 Medium 模型校验/修复' -ForegroundColor Cyan;Write-Host '版本：0.2.1';Write-Host "模型目录：$Models";Write-Host '已有完整模型不会重复下载。';Write-Host ''
 for($i=0;$i-lt $Specs.Count;$i++){$spec=$Specs[$i];$target=Join-Path $Models $spec.File;$base=5+[int](90*$i/$Specs.Count);$next=5+[int](90*($i+1)/$Specs.Count);$span=$next-$base;Set-Gui $base ("正在校验 "+$spec.Name) $spec.File;if((Test-Path $target)-and(Get-Item $target).Length-ge $spec.Min-and(Hash-Ok $target $spec.Sha)){Write-Host("[OK] {0} 已存在 ({1})"-f$spec.Name,(Size-Text(Get-Item $target).Length))-ForegroundColor Green;Set-Gui $next ("已找到 "+$spec.Name) '工程内文件完整，不需要联网。';continue};Remove-Item $target -Force -ErrorAction SilentlyContinue;$reuse=Find-Reusable $spec;if($reuse){Copy-Item $reuse $target -Force;Write-Host("[OK] {0} 从本机复用：{1}"-f$spec.Name,$reuse)-ForegroundColor Green;Set-Gui $next ("已复用 "+$spec.Name) '不需要联网。';continue};Write-Host("[INFO] 缺少 {0}，开始联网下载。"-f$spec.Name)-ForegroundColor Yellow;Download-One $spec $target $base $span;Write-Host("[OK] {0} 下载完成"-f$spec.Name)-ForegroundColor Green}
 $dict=Join-Path $Models 'ppocrv6_medium_dict.txt';$lines=(Get-Content $dict -Encoding UTF8|Measure-Object -Line).Lines;if($lines-lt 18000){throw"字典异常：只有 $lines 行。"};Set-Gui 100 '模型校验完成' 'PP-OCRv6 Medium DET / REC / 字典均已就绪。';Write-Host '';Write-Host '模型校验完成。' -ForegroundColor Green;Log 'model verification completed';if($GuiMode -and $GuiForm){Start-Sleep -Milliseconds 200;$GuiForm.Close();$GuiForm.Dispose()};exit 0
}catch{Log('FAILED: '+$_.Exception.ToString());Write-Host '';Write-Host '模型准备失败。' -ForegroundColor Red;Write-Host $_.Exception.Message -ForegroundColor Red;Write-Host"日志：$LogFile";if($GuiMode -and $GuiForm){$GuiForm.Close();$GuiForm.Dispose();[Windows.Forms.MessageBox]::Show("模型准备失败。`r`n`r`n$($_.Exception.Message)`r`n`r`n日志：$LogFile",'OCRCaptureTool Full','OK','Error')|Out-Null};exit 1}
